      "command": "if rpm --quiet -q kernel-core; then var_accounts_tmout=''\n# if 0, no occurrence of tmout found, if 1, occurrence found tmout_found=0 for f in /etc/profile /etc/profile.d/*.sh;\ndo if grep --silent '^[^#].*TMOUT' $f; then sed -i -E \"s/^(.*)TMOUT\\\\s*=\\\\s*(\\\\.|\\\\$)*(.*)$/typeset -xr TMOUT=$var_accounts_tmout\\\\3/g\"\n$f tmout_found=1 fi done if [ $tmout_found -eq 0 ]; then echo -e \"\\\\n# Set TMOUT to $var_accounts_tmout per security requirements\" >> /etc/profile.d/tmout.sh\necho \"typeset -xr TMOUT=$var_accounts_tmout\" >> /etc/profile.d"
    }
  ]
}

